import React, { useState } from 'react';
import { Canvas } from '@react-three/fiber';
import STLViewer from './STLViewer'; // Assuming the STLViewer is in the same folder
import { OrbitControls } from '@react-three/drei';

function App() {
  // Set path to the STL file you want to load
  const stlPath = '/path/to/your/model.stl'; // Replace with your actual STL file path

  return (
    <div style={{ height: '100vh', width: '100%' }}>
      <Canvas>
        <ambientLight intensity={0.5} />
        <directionalLight position={[10, 10, 10]} intensity={1} />
        {/* Add OrbitControls to make the model interactive */}
        <OrbitControls />
        <STLViewer path={stlPath} />
      </Canvas>
    </div>
  );
}

export default App;
